/* Landing page — roastery in Brno. Tokens only (maude DS, light theme). Flow layout,
 * reflow by container width (.lp is the container) — never vw/vh, never absolute. */

.lp {
  container-type: inline-size;
  min-height: 100%;
  background: var(--bg-0);
  color: var(--fg-0);
  font-family: var(--font-body);
  font-size: var(--type-base);
  line-height: var(--lh-base);
}
.lp *, .lp *::before, .lp *::after { box-sizing: border-box; }
.lp a { color: inherit; text-decoration: none; }
.lp h1, .lp h2, .lp h3, .lp p, .lp ul, .lp dl, .lp dd, .lp figure { margin: 0; padding: 0; }
.lp ul { list-style: none; }

.lp-wrap { width: 100%; max-width: 1200px; margin: 0 auto; padding: 0 var(--space-8); }
.lp-eyebrow {
  font-family: var(--font-mono); font-size: var(--type-xs); line-height: var(--lh-xs);
  letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--fg-2);
}
.lp-h2 {
  font-family: var(--font-display); font-weight: var(--weight-semibold);
  font-size: var(--type-3xl); line-height: var(--lh-3xl); letter-spacing: var(--tracking-tight);
}
.lp-lede { color: var(--fg-1); font-size: var(--type-md); line-height: var(--lh-md); max-width: 52ch; }
.lp-section { padding: calc(var(--space-8) * 2) 0; }
.lp-sec-hd { display: grid; gap: var(--space-3); margin-bottom: var(--space-8); }

/* ── Nav ─────────────────────────────────────────────────────────────────── */
.lp-nav { border-bottom: 1px solid var(--border-subtle); background: var(--bg-1); }
.lp-nav .lp-wrap { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); height: calc(var(--space-8) + var(--space-5)); }
.lp-brand { display: inline-flex; align-items: center; gap: var(--space-3); font-family: var(--font-display); font-weight: var(--weight-semibold); font-size: var(--type-md); letter-spacing: var(--tracking-tight); }
.lp-brand svg { color: var(--accent); }
.lp-links { display: flex; align-items: center; gap: var(--space-6); color: var(--fg-1); font-size: var(--type-sm); }
.lp-links a:hover { color: var(--fg-0); }

/* ── Hero ────────────────────────────────────────────────────────────────── */
.lp-hero { padding: calc(var(--space-8) * 2) 0 calc(var(--space-8) + var(--space-6)); }
.lp-hero .lp-wrap { display: grid; grid-template-columns: 1.15fr 1fr; gap: calc(var(--space-8) + var(--space-6)); align-items: center; }
.lp-hero-copy { display: grid; gap: var(--space-5); justify-items: start; }
.lp-h1 {
  font-family: var(--font-display); font-weight: var(--weight-semibold);
  font-size: calc(var(--type-3xl) * 1.9); line-height: 1.04; letter-spacing: var(--tracking-tight);
}
.lp-cta { display: flex; flex-wrap: wrap; gap: var(--space-3); margin-top: var(--space-3); }
.lp-cta .btn { padding: var(--space-4) var(--space-6); font-size: var(--type-base); }

.lp-hero-art {
  position: relative; display: grid; place-items: center;
  aspect-ratio: 1 / 1; border-radius: var(--radius-xl);
  background: var(--bg-2); border: 1px solid var(--border-subtle); overflow: hidden;
}
.lp-hero-art > svg { width: 78%; height: auto; color: var(--fg-1); }
.lp-ticket {
  position: absolute; left: var(--space-5); right: var(--space-5); bottom: var(--space-5);
  background: var(--bg-1); border: 1px solid var(--border-default); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md); padding: var(--space-4) var(--space-5);
  display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3) var(--space-5);
}
.lp-ticket dt { font-family: var(--font-mono); font-size: var(--type-xs); letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--fg-2); }
.lp-ticket dd { font-family: var(--font-mono); font-size: var(--type-sm); color: var(--fg-0); }

/* ── Facts strip ─────────────────────────────────────────────────────────── */
.lp-facts { border-block: 1px solid var(--border-subtle); background: var(--bg-1); }
.lp-facts ul { display: grid; grid-template-columns: repeat(4, 1fr); }
.lp-facts li { display: grid; gap: var(--space-2); padding: var(--space-6) var(--space-6); border-left: 1px solid var(--border-subtle); }
.lp-facts li:first-child { border-left: 0; padding-left: 0; }
.lp-fact-n { font-family: var(--font-mono); font-size: var(--type-2xl); line-height: var(--lh-2xl); font-weight: var(--weight-medium); }
.lp-fact-l { color: var(--fg-1); font-size: var(--type-sm); line-height: var(--lh-sm); }

/* ── Beans ───────────────────────────────────────────────────────────────── */
.lp-beans { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
.lp-card {
  display: grid; gap: var(--space-5); align-content: start; padding: var(--space-6);
  background: var(--bg-1); border: 1px solid var(--border-default); border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}
.lp-card-art { display: grid; place-items: center; height: 148px; border-radius: var(--radius-md); background: var(--bg-2); }
.lp-card-art svg { height: 96px; width: auto; }
.lp-card-hd { display: grid; gap: var(--space-2); }
.lp-card h3 { font-family: var(--font-display); font-weight: var(--weight-semibold); font-size: var(--type-xl); line-height: var(--lh-xl); letter-spacing: var(--tracking-tight); }
.lp-card-notes { color: var(--fg-1); }
.lp-roast { display: flex; align-items: center; gap: var(--space-3); font-family: var(--font-mono); font-size: var(--type-xs); letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--fg-2); }
.lp-roast-bar { display: flex; gap: var(--space-2); }
.lp-roast-bar i { width: var(--space-6); height: var(--space-3); border-radius: var(--radius-pill); background: var(--bg-4); }
.lp-roast-bar i.on { background: var(--accent); }
.lp-card-ft { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); padding-top: var(--space-5); border-top: 1px solid var(--border-subtle); }
.lp-price { font-family: var(--font-mono); font-size: var(--type-md); font-weight: var(--weight-medium); }
.lp-price small { color: var(--fg-2); font-size: var(--type-xs); font-weight: var(--weight-regular); }

/* ── Process ─────────────────────────────────────────────────────────────── */
.lp-process { background: var(--bg-1); border-block: 1px solid var(--border-subtle); }
.lp-steps { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-8); }
.lp-step { display: grid; gap: var(--space-3); align-content: start; padding-top: var(--space-5); border-top: 2px solid var(--fg-0); }
.lp-step-n { font-family: var(--font-mono); font-size: var(--type-xs); letter-spacing: var(--tracking-wide); color: var(--fg-2); }
.lp-step h3 { font-family: var(--font-display); font-weight: var(--weight-semibold); font-size: var(--type-xl); line-height: var(--lh-xl); }
.lp-step p { color: var(--fg-1); }

/* ── Visit ───────────────────────────────────────────────────────────────── */
.lp-visit .lp-wrap { display: grid; grid-template-columns: 1fr 1fr; gap: calc(var(--space-8) + var(--space-6)); align-items: center; }
.lp-visit-copy { display: grid; gap: var(--space-5); justify-items: start; }
.lp-hours { width: 100%; display: grid; gap: 0; border-top: 1px solid var(--border-default); }
.lp-hours div { display: flex; justify-content: space-between; gap: var(--space-5); padding: var(--space-4) 0; border-bottom: 1px solid var(--border-subtle); }
.lp-hours dt { color: var(--fg-1); }
.lp-hours dd { font-family: var(--font-mono); font-size: var(--type-sm); }
.lp-addr { font-family: var(--font-mono); font-size: var(--type-sm); color: var(--fg-1); }
.lp-map { aspect-ratio: 4 / 3; border-radius: var(--radius-xl); background: var(--bg-2); border: 1px solid var(--border-subtle); overflow: hidden; }
.lp-map svg { display: block; width: 100%; height: 100%; }

/* ── Subscribe ───────────────────────────────────────────────────────────── */
.lp-sub .lp-wrap { padding-top: 0; padding-bottom: calc(var(--space-8) * 2); }
.lp-sub-box {
  display: grid; grid-template-columns: 1.2fr 1fr; gap: var(--space-8); align-items: center;
  padding: calc(var(--space-8) + var(--space-3)); border-radius: var(--radius-xl);
  background: var(--bg-1); border: 1px solid var(--border-default);
}
.lp-sub-box > div { display: grid; gap: var(--space-3); }
.lp-form { display: grid; gap: var(--space-3); }
.lp-form label { font-family: var(--font-mono); font-size: var(--type-xs); letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--fg-2); }
.lp-form-row { display: flex; gap: var(--space-3); }
.lp-form-row .input { flex: 1; min-width: 0; padding: var(--space-4); font-size: var(--type-base); }
.lp-form-row .btn { padding: var(--space-4) var(--space-6); font-size: var(--type-base); }
.lp-form small { color: var(--fg-2); font-size: var(--type-xs); line-height: var(--lh-xs); }

/* ── Footer ──────────────────────────────────────────────────────────────── */
.lp-foot { border-top: 1px solid var(--border-subtle); background: var(--bg-1); }
.lp-foot .lp-wrap { display: flex; align-items: center; justify-content: space-between; gap: var(--space-6); padding-top: var(--space-6); padding-bottom: var(--space-6); color: var(--fg-2); font-size: var(--type-sm); }
.lp-foot ul { display: flex; gap: var(--space-6); }
.lp-foot a:hover { color: var(--fg-0); }

/* ── Tablet ──────────────────────────────────────────────────────────────── */
@container (max-width: 900px) {
  .lp-wrap { padding: 0 var(--space-7); }
  .lp-section { padding: calc(var(--space-8) + var(--space-6)) 0; }
  .lp-hero { padding-top: calc(var(--space-8) + var(--space-6)); }
  .lp-hero .lp-wrap { grid-template-columns: 1fr; gap: var(--space-8); }
  .lp-h1 { font-size: calc(var(--type-3xl) * 1.5); }
  .lp-hero-art { aspect-ratio: 4 / 3; }
  .lp-hero-art > svg { width: auto; height: 80%; }
  .lp-facts ul { grid-template-columns: repeat(2, 1fr); }
  .lp-facts li:nth-child(3) { border-left: 0; padding-left: 0; }
  .lp-facts li:nth-child(n + 3) { border-top: 1px solid var(--border-subtle); }
  .lp-beans { grid-template-columns: repeat(2, 1fr); }
  .lp-steps { grid-template-columns: 1fr; gap: var(--space-6); }
  .lp-visit .lp-wrap { grid-template-columns: 1fr; gap: var(--space-8); }
  .lp-sub-box { grid-template-columns: 1fr; gap: var(--space-6); padding: var(--space-7); }
}

/* ── Mobile ──────────────────────────────────────────────────────────────── */
@container (max-width: 520px) {
  .lp-wrap { padding: 0 var(--space-5); }
  .lp-section { padding: var(--space-8) 0; }
  .lp-sec-hd { margin-bottom: var(--space-6); }
  .lp-links a:not(.btn) { display: none; }
  .lp-hero { padding: var(--space-8) 0; }
  .lp-h1 { font-size: calc(var(--type-3xl) * 1.1); line-height: 1.1; }
  .lp-cta .btn { flex: 1 1 100%; justify-content: center; }
  .lp-hero-art { aspect-ratio: 1 / 1.05; }
  .lp-ticket { left: var(--space-4); right: var(--space-4); bottom: var(--space-4); padding: var(--space-4); gap: var(--space-3) var(--space-4); }
  .lp-h2 { font-size: var(--type-2xl); line-height: var(--lh-2xl); }
  .lp-facts li { padding: var(--space-5) var(--space-4); }
  .lp-facts li:nth-child(odd) { padding-left: 0; }
  .lp-fact-n { font-size: var(--type-xl); line-height: var(--lh-xl); }
  .lp-beans { grid-template-columns: 1fr; }
  .lp-sub-box { padding: var(--space-6) var(--space-5); }
  .lp-form-row { flex-direction: column; }
  .lp-form-row .btn { justify-content: center; }
  .lp-foot .lp-wrap { flex-direction: column; align-items: flex-start; gap: var(--space-4); }
}
